import React, { useRef } from 'react';
import { Settings } from '../types';
import { X, Ghost, EyeOff, Volume2, Music, Download, Upload, Database } from 'lucide-react';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: Settings;
  setSettings: (s: Settings) => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, settings, setSettings }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const toggleGhost = () => setSettings({ ...settings, ghostEnabled: !settings.ghostEnabled });
  const toggleReadAhead = () => setSettings({ ...settings, readAheadEnabled: !settings.readAheadEnabled });
  const toggleSfx = () => setSettings({ ...settings, sfxEnabled: !settings.sfxEnabled });

  // Ambient volume control (for generated music)
  const handleVolumeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSettings({ ...settings, ambientVolume: parseFloat(e.target.value) });
  };

  const handleExport = () => {
    const data: Record<string, string> = {};
    let count = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      // Capture all keys related to Frog Type
      if (key && (key.startsWith('frogType_') || key === 'frogXP')) {
        data[key] = localStorage.getItem(key) || "";
        count++;
      }
    }

    if (count === 0) {
        alert("No game data found to export.");
        return;
    }

    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `frog-type-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);

        if (typeof json !== 'object' || json === null) {
            throw new Error("Invalid file format");
        }

        // Validate that it looks like a frog backup (check for at least one known key or just generic structure)
        const keys = Object.keys(json);
        const hasValidKeys = keys.some(k => k.startsWith('frogType_') || k === 'frogXP');

        if (!hasValidKeys) {
             if (!confirm("This file doesn't look like a valid Frog Type backup. Try to import anyway?")) {
                 return;
             }
        }

        if (confirm("This will overwrite your current progress. Are you sure?")) {
            keys.forEach(key => {
               // Only restore frog related keys for safety
               if (key.startsWith('frogType_') || key === 'frogXP') {
                 localStorage.setItem(key, json[key]);
               }
            });

            alert("Backup restored successfully! The page will now reload.");
            window.location.reload();
        }
      } catch (err) {
        alert("Failed to restore backup: Invalid file format.");
        console.error(err);
      }

      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-stone-900/20 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm overflow-hidden flex flex-col max-h-[85vh]">
        <div className="flex justify-between items-center p-4 border-b border-stone-100 bg-white sticky top-0 z-10">
          <h2 className="text-lg font-bold text-stone-700 flex items-center gap-2">
            Settings
          </h2>
          <button onClick={onClose} className="text-stone-400 hover:text-stone-600">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-4 space-y-4 overflow-y-auto custom-scrollbar">

          {/* Sound Effects Toggle (Teal) */}
          <div 
            onClick={toggleSfx}
            className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${settings.sfxEnabled ? 'bg-teal-50 border-teal-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.sfxEnabled ? 'bg-teal-100 text-teal-600' : 'bg-stone-200 text-stone-500'}`}>
                <Volume2 className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Sound Effects</div>
                <div className="text-[10px] text-stone-400">Game status sounds</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.sfxEnabled ? 'bg-teal-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.sfxEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </div>

          {/* Master Volume (Controls Brown Noise / Piano etc) */}
          <div className="p-3 rounded-xl border bg-stone-50 border-stone-100">
            <div className="flex items-center gap-3 mb-3">
               <div className="p-2 rounded-lg bg-stone-200 text-stone-500">
                  <Music className="w-5 h-5" />
               </div>
               <div>
                  <div className="font-bold text-sm text-stone-700">Volume</div>
                  <div className="text-[10px] text-stone-400">Generated music & ambience</div>
               </div>
            </div>
            <div className="px-1">
                <div className="flex justify-between text-[10px] text-stone-400 font-bold mb-1 uppercase tracking-wide">
                    <span>Volume</span>
                    <span>{Math.round(settings.ambientVolume * 100)}%</span>
                </div>
                <input 
                  type="range" 
                  min="0" 
                  max="1" 
                  step="0.01" 
                  value={settings.ambientVolume}
                  onChange={handleVolumeChange}
                  className="w-full h-1.5 bg-stone-200 rounded-lg appearance-none cursor-pointer accent-stone-500"
                />
            </div>
          </div>

          {/* Ghost Mode Toggle */}
          <div 
            onClick={toggleGhost}
            className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${settings.ghostEnabled ? 'bg-purple-50 border-purple-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.ghostEnabled ? 'bg-purple-100 text-purple-600' : 'bg-stone-200 text-stone-500'}`}>
                <Ghost className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Ghost Replay</div>
                <div className="text-[10px] text-stone-400">Race against your previous speed</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.ghostEnabled ? 'bg-purple-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.ghostEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </div>

          {/* Read Ahead Toggle */}
          <div 
             onClick={toggleReadAhead}
             className={`flex items-center justify-between p-3 rounded-xl cursor-pointer border transition-all ${settings.readAheadEnabled ? 'bg-frog-50 border-frog-200' : 'bg-stone-50 border-transparent hover:bg-stone-100'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`p-2 rounded-lg ${settings.readAheadEnabled ? 'bg-frog-100 text-frog-600' : 'bg-stone-200 text-stone-500'}`}>
                <EyeOff className="w-5 h-5" />
              </div>
              <div>
                <div className="font-bold text-sm text-stone-700">Read Ahead Mode</div>
                <div className="text-[10px] text-stone-400">Hide current word to force focus</div>
              </div>
            </div>
            <div className={`w-10 h-6 rounded-full relative transition-colors ${settings.readAheadEnabled ? 'bg-frog-500' : 'bg-stone-300'}`}>
               <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${settings.readAheadEnabled ? 'left-5' : 'left-1'}`} />
            </div>
          </div>

          {/* Backup & Restore Section */}
          <div className="pt-4 border-t border-stone-100">
             <div className="flex items-center gap-2 mb-3 text-stone-400 font-bold text-xs uppercase tracking-wider">
                <Database className="w-3 h-3" /> Data & Backup
             </div>
             <div className="grid grid-cols-2 gap-3">
                <button 
                  onClick={handleExport}
                  className="flex flex-col items-center justify-center gap-2 p-3 rounded-xl bg-stone-50 border border-stone-200 hover:bg-stone-100 hover:border-stone-300 transition-all text-stone-600"
                >
                    <Download className="w-5 h-5" />
                    <span className="text-xs font-bold">Export Save</span>
                </button>
                <button 
                  onClick={handleImportClick}
                  className="flex flex-col items-center justify-center gap-2 p-3 rounded-xl bg-stone-50 border border-stone-200 hover:bg-stone-100 hover:border-stone-300 transition-all text-stone-600 relative"
                >
                    <Upload className="w-5 h-5" />
                    <span className="text-xs font-bold">Import Save</span>
                    <input 
                        type="file" 
                        ref={fileInputRef}
                        onChange={handleImportFile}
                        accept=".json"
                        className="hidden"
                    />
                </button>
             </div>
             <p className="text-[10px] text-stone-400 mt-2 text-center">
                Export your progress to a file to transfer to another device or keep as a backup.
             </p>
          </div>

        </div>

        <div className="p-4 bg-stone-50 text-center border-t border-stone-100">
            <button onClick={onClose} className="text-xs font-bold text-stone-500 hover:text-stone-700">Close</button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;
